'use strict';
const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs');
const {setup}=require('../../../qa-artifacts/qa-cycle-20261026/cycle15/story/repair/setup.cjs'),old=require('./baseline.json');
function h(){let x=setup();x.run("S.at='muju';S.scrap=10;S.items['부품']=0;S.party=['minji'];UI.showEvent=e=>G.beginPresentation(e);globalThis.e=event('jy_recruit');");return x}
const state=x=>x.run('JSON.stringify([S.day,S.min,S.scrap,S.items,S.notes,S.comps,S.recruitQ])');
test('처음 정보 구매는 고철 3에 부품 1, 반복 판매 숨김, 무료 유보와 다음 재영입',()=>{let x=h();assert(x.run("G.openRecruitMeet('jaeyi')"));assert(x.run('G.reqVisible(G.choiceReq(e.choices[1]))&&G.reqOk(G.choiceReq(e.choices[1])).ok'));assert(!x.run('G.reqVisible(G.choiceReq(e.choices[2]))'));x.run('G.pickOutcome=()=>e.choices[1].out[0];globalThis.r=G.resolvePresentedChoice(e,e.choices[1])');assert(x.run('r.applied'));assert.equal(x.run('S.scrap'),7);assert.equal(x.run("S.items['부품']"),1);assert(x.run('S.flags.jaeyi_info_bought'));x.run('G.queuePresentation(null);G.save();G.load()');assert(x.run("G.openRecruitMeet('jaeyi')"));assert.equal(x.run('G.reqVisible(G.choiceReq(e.choices[1]))'),false);assert.equal(x.run('G.reqOk(G.choiceReq(e.choices[1])).ok'),false);let blocked=state(x);x.run('r=G.resolvePresentedChoice(e,e.choices[1])');assert.equal(x.run('r.ok'),false);assert.equal(state(x),blocked);assert(x.run('G.reqVisible(G.choiceReq(e.choices[2]))&&G.reqOk(G.choiceReq(e.choices[2])).ok'));assert.match(x.run('e.choices[2].label'),/나중|다음|생각/);let before=state(x);x.run('G.pickOutcome=()=>e.choices[2].out[0];r=G.resolvePresentedChoice(e,e.choices[2])');assert(x.run('r.applied'));assert.equal(state(x),before);x.run('G.queuePresentation(null)');assert(x.run("G.openRecruitMeet('jaeyi')"));x.run('G.pickOutcome=()=>e.choices[0].out[0];r=G.resolvePresentedChoice(e,e.choices[0])');assert(x.run("r.applied&&S.recruitQ.id==='jaeyi'"));});
test('원래 두 선택의 본문 및 비용 유지하고 구매 flag 외 효과 보존',()=>{let x=h(),now=x.json('e.choices'),was=old.events.jy_recruit.choices;assert.equal(now[0].label,was[0].label);assert.deepEqual(now[0].out,was[0].out);assert.equal(now[1].label,was[1].label);assert.equal(now[1].out[0].text,was[1].out[0].text);delete now[1].out[0].fx.flag;delete now[1].req.notFlag;assert.deepEqual(now.slice(0,2),was)});
test('민지 공구함 첫 결과 수첩이 본문에서 확인된 선물 사실만 기록',()=>{let x=h();x.run("globalThis.m=event('minji_toolbox');G.beginPresentation(m);G.pickOutcome=()=>m.choices[0].out[0];globalThis.r=G.resolvePresentedChoice(m,m.choices[0])");assert(x.run('r.applied'));assert.match(x.run('S.notes.find(n=>n.title===\'여러 해 할부 공구함\').body'),/할부.*취직 선물/);assert.doesNotMatch(x.run("S.notes.find(n=>n.title==='여러 해 할부 공구함').body"),/공구 받침 밑/)});
for(const id of ['jy_recruit','minji_toolbox'])for(let ci=0;ci<2;ci++)test(id+'.'+ci+' 구 지급 기록 본문과 효과 보존',()=>{let x=h(),o=old.paid[id+':'+ci];assert(x.run('G.load('+JSON.stringify(o.save)+')'));let before=state(x);x.run(`globalThis.e=event('${id}'),r=G.resolvePresentedChoice(e,e.choices[${ci}])`);assert.equal(x.run('r.applied'),false);assert.equal(x.run('r.out.text'),o.text);assert.equal(state(x),before)});
test('옛 미지급 자연 저장은 구매 후 새 가드를 얻고 본문을 유지',()=>{let x=h(),raw=fs.readFileSync(require('node:path').resolve(__dirname,'normal-unpaid-271-jy_recruit.json'),'utf8');assert(x.run('G.load('+JSON.stringify(raw)+')'));x.run("globalThis.e=event('jy_recruit');G.pickOutcome=()=>e.choices[1].out[0];globalThis.r=G.resolvePresentedChoice(e,e.choices[1])");assert(x.run('r.applied&&S.flags.jaeyi_info_bought'));assert.equal(x.run('r.out.text'),old.paid['jy_recruit:1'].text);});
test('공구함은 첫 수첩 본문 외 모든 결과와 효과를 유지',()=>{let x=h(),now=x.json("JSON.parse(JSON.stringify(event('minji_toolbox'),(k,v)=>typeof v==='function'?v.toString():v))"),was=old.events.minji_toolbox;assert.equal(now.choices[0].out[0].fx.note.body,'민규가 할부로 사 준 취직 선물. 민지는 공구함을 닫다가 사진을 한 번 더 보았다.');now.choices[0].out[0].fx.note.body=was.choices[0].out[0].fx.note.body;assert.deepEqual(now,was)});
test('실제 UI 선택지 렌더러는 숨김 조건 및 무료 유보 버튼을 사용',()=>{let ui=fs.readFileSync('src/07-ui.js','utf8'),body=ui.slice(ui.indexOf('  function eventChoiceData('),ui.indexOf('  function eventSceneKeys('));assert.match(body,/G\.reqVisible\(req\)/);assert.match(body,/'notFlag'/);assert.match(body,/!requirementVisible&&spoilerLocked/);let x=h();x.run("S.flags.jaeyi_info_bought=true");assert.equal(x.run('G.reqVisible(G.choiceReq(e.choices[1]))'),false);assert(x.run('G.reqVisible(G.choiceReq(e.choices[2]))'));assert.equal(x.run('G.reqCostText(G.choiceReq(e.choices[2]))'),'');});
for(const id of ['jy_recruit','minji_toolbox'])for(let ci=0;ci<2;ci++)test(id+'.'+ci+' 구 결과 저장 reader 복원',()=>{const o=old.paid[id+':'+ci],x=h(),raw=JSON.parse(o.save);assert(x.run('G.load('+JSON.stringify(o.save)+')'));x.run(`globalThis.e=event('${id}'),t=buildStoryTurns(${JSON.stringify(o.text)},e,{turnSpeakers:e.choices[${ci}].out[0].turnSpeakers})`);const turns=x.json('t');raw.pendingPresentation.reading={eventId:id,phase:'outcome',view:{turns,index:0},history:null,selection:'옛 선택',updates:[]};assert(x.run('G.load('+JSON.stringify(JSON.stringify(raw))+')'));const before=state(x);x.run(`globalThis.e=event('${id}'),r=G.resolvePresentedChoice(e,e.choices[${ci}])`);assert.equal(x.run('r.applied'),false);assert.deepEqual(x.json('r.out.turns'),turns);assert.equal(state(x),before)});
